/**
 * FAF Process Module — faf_process.c
 * FreeLang Agent Framework
 *
 * popen() 기반 쉘 명령 실행
 * 출력: stdout + stderr 캡처
 * 반환: { stdout, exitCode }
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_OUTPUT 65536  /* 64KB */
#define MAX_CMD    4096

/**
 * exec_command - 명령어 실행 후 stdout 반환
 * @cmd: 실행할 명령어 (쉘 문자열)
 * @out: 출력 버퍼 (호출자가 MAX_OUTPUT 이상 할당)
 * @returns: exit code (0 = 성공)
 */
int exec_command(const char *cmd, char *out, int out_size) {
    char buf[256];
    FILE *fp;
    int total = 0;
    int exit_code;

    /* stderr도 캡처 */
    char full_cmd[MAX_CMD];
    snprintf(full_cmd, sizeof(full_cmd), "%s 2>&1", cmd);

    fp = popen(full_cmd, "r");
    if (!fp) {
        snprintf(out, out_size, "ERROR: popen failed: %s", strerror(errno));
        return -1;
    }

    out[0] = '\0';
    while (fgets(buf, sizeof(buf), fp) != NULL) {
        int len = strlen(buf);
        if (total + len < out_size - 1) {
            strcat(out, buf);
            total += len;
        }
    }

    exit_code = pclose(fp);
    /* WEXITSTATUS: 실제 종료 코드 추출 */
    if (exit_code != -1 && WIFEXITED(exit_code))
        exit_code = WEXITSTATUS(exit_code);

    return exit_code;
}

/**
 * exec_get_stdout - 결과만 반환 (테스트용)
 */
char* exec_get_stdout(const char *cmd) {
    static char out[MAX_OUTPUT];
    exec_command(cmd, out, sizeof(out));
    return out;
}

/* ── FreeLang FFI 진입점 ── */

/**
 * fl_process_exec(cmd) -> { stdout: string, exitCode: int }
 * FreeLang에서 호출: $ffi.fl_process_exec("ls -la")
 */
void fl_process_exec(const char *cmd, char *stdout_out, int *exit_code_out) {
    *exit_code_out = exec_command(cmd, stdout_out, MAX_OUTPUT);
}

/**
 * fl_process_exec_simple(cmd) -> string
 * 단순 버전: 출력만 반환
 */
const char* fl_process_exec_simple(const char *cmd) {
    return exec_get_stdout(cmd);
}

