 * FreeLang Agent Framework
 *
 * fork+exec 기반 쉘 명령 실행 (Termux 호환)
 * popen()은 Termux에서 /bin/sh 못 찾아 127 반환 → fork+exec 사용
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

#define MAX_OUTPUT 65536
#define BASH_PATH  "/data/data/com.termux/files/usr/bin/bash"

/**
 * exec_command - bash -c로 명령 실행
 * @cmd:      실행할 명령어
 * @out:      stdout+stderr 출력 버퍼
 * @out_size: 버퍼 크기
 * @returns:  exit code (0 = 성공)
 */
int exec_command(const char *cmd, char *out, int out_size) {
    int pipefd[2];
    int total = 0;
    char buf[4096];
    int n, status;

    out[0] = '\0';

    if (pipe(pipefd) < 0) {
        snprintf(out, out_size, "ERROR: pipe failed: %s", strerror(errno));
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        close(pipefd[0]);
        close(pipefd[1]);
        snprintf(out, out_size, "ERROR: fork failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        /* 자식 프로세스: stdout + stderr → pipe */
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[1]);
        execl(BASH_PATH, "bash", "-c", cmd, NULL);
        _exit(127);
    }

    /* 부모 프로세스: 출력 읽기 */
    close(pipefd[1]);
    while ((n = read(pipefd[0], buf, sizeof(buf) - 1)) > 0) {
        buf[n] = '\0';
        if (total + n < out_size - 1) {
            strncat(out, buf, out_size - total - 1);
            total += n;
        }
    }
    close(pipefd[0]);

    waitpid(pid, &status, 0);
    return WIFEXITED(status) ? WEXITSTATUS(status) : -1;
}

/* ── FreeLang FFI 진입점 ── */

void fl_process_exec(const char *cmd, char *stdout_out, int *exit_code_out) {
    *exit_code_out = exec_command(cmd, stdout_out, MAX_OUTPUT);
}

const char* fl_process_exec_simple(const char *cmd) {
    static char out[MAX_OUTPUT];
    exec_command(cmd, out, sizeof(out));
    return out;
}

