} HttpResponse;

/**
 * run_cmd - bash -c로 명령 실행 후 stdout 반환
 */
static int run_cmd(const char *cmd, char *out, int out_size) {
    int pipefd[2];
    int total = 0, n, status;
    char buf[8192];

    out[0] = '\0';
    if (pipe(pipefd) < 0) return -1;

    pid_t pid = fork();
    if (pid < 0) { close(pipefd[0]); close(pipefd[1]); return -1; }

    if (pid == 0) {
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        dup2(pipefd[1], STDERR_FILENO);
        close(pipefd[1]);
        execl(BASH_PATH, "bash", "-c", cmd, NULL);
        _exit(127);
    }

    close(pipefd[1]);
    while ((n = read(pipefd[0], buf, sizeof(buf) - 1)) > 0) {
        buf[n] = '\0';
        if (total + n < out_size - 1) {
            strncat(out, buf, out_size - total - 1);
            total += n;
        }
