/**
 * FAF HTTP Client — faf_http_client.c
 * FreeLang Agent Framework
 *
 * curl 프로세스 기반 HTTP 클라이언트
 * Claude API 호출에 최적화
 *
 * 전략: libcurl 대신 curl CLI → popen()
 * 이유: Termux 환경에서 curl 바이너리 보장됨
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define MAX_BODY    262144  /* 256KB — Claude 응답 충분 */
#define MAX_CMD     8192
#define MAX_HEADERS 2048

typedef struct {
    char body[MAX_BODY];
    int  status_code;
    char error[256];
} HttpResponse;

/**
 * http_post - POST 요청
 * @url:     요청 URL
 * @body:    JSON body 문자열
 * @headers: HTTP 헤더 배열 (NULL 종료)
 * @resp:    응답 저장 구조체
 */
void http_post(const char *url, const char *body,
               const char **headers, HttpResponse *resp) {
    char cmd[MAX_CMD];
    char header_args[MAX_HEADERS] = "";
    FILE *fp;

    resp->body[0] = '\0';
    resp->status_code = 0;
    resp->error[0] = '\0';

    /* 헤더 조립 */
    if (headers) {
        for (int i = 0; headers[i] != NULL; i++) {
            char h[256];
            snprintf(h, sizeof(h), " -H '%s'", headers[i]);
            strncat(header_args, h, sizeof(header_args) - strlen(header_args) - 1);
        }
    }

    /* curl 명령 조립
     * -s: silent
     * -w: write-out (status code 마지막에 출력)
     * -X POST
     * -d: body
     * --max-time 30: 타임아웃
     */
    snprintf(cmd, sizeof(cmd),
        "curl -s -w '\\nHTTP_STATUS:%%{http_code}'"
        " -X POST"
        " -H 'Content-Type: application/json'"
        "%s"
        " --max-time 30"
        " -d '%s'"
        " '%s' 2>&1",
        header_args, body, url);

    fp = popen(cmd, "r");
    if (!fp) {
        snprintf(resp->error, sizeof(resp->error),
                 "popen failed: %s", strerror(errno));
        resp->status_code = -1;
        return;
    }

    /* 출력 읽기 */
    char buf[4096];
    int total = 0;
    while (fgets(buf, sizeof(buf), fp) != NULL) {
        /* 마지막 줄: HTTP_STATUS:200 */
        if (strncmp(buf, "\nHTTP_STATUS:", 13) == 0 ||
            strncmp(buf, "HTTP_STATUS:", 12) == 0) {
            char *p = strstr(buf, "HTTP_STATUS:");
            if (p) resp->status_code = atoi(p + 12);
        } else {
            int len = strlen(buf);
            if (total + len < MAX_BODY - 1) {
                strncat(resp->body, buf, MAX_BODY - total - 1);
                total += len;
            }
        }
    }

    pclose(fp);
}

/**
 * http_get - GET 요청
 */
void http_get(const char *url, const char **headers, HttpResponse *resp) {
    char cmd[MAX_CMD];
    char header_args[MAX_HEADERS] = "";
    FILE *fp;

    resp->body[0] = '\0';
    resp->status_code = 0;
    resp->error[0] = '\0';

    if (headers) {
        for (int i = 0; headers[i] != NULL; i++) {
            char h[256];
            snprintf(h, sizeof(h), " -H '%s'", headers[i]);
            strncat(header_args, h, sizeof(header_args) - strlen(header_args) - 1);
        }
    }

    snprintf(cmd, sizeof(cmd),
        "curl -s -w '\\nHTTP_STATUS:%%{http_code}'"
        "%s"
        " --max-time 30"
        " '%s' 2>&1",
        header_args, url);

    fp = popen(cmd, "r");
    if (!fp) {
        snprintf(resp->error, sizeof(resp->error),
                 "popen failed: %s", strerror(errno));
        resp->status_code = -1;
        return;
    }

    char buf[4096];
    int total = 0;
    while (fgets(buf, sizeof(buf), fp) != NULL) {
        if (strncmp(buf, "\nHTTP_STATUS:", 13) == 0 ||
            strncmp(buf, "HTTP_STATUS:", 12) == 0) {
            char *p = strstr(buf, "HTTP_STATUS:");
            if (p) resp->status_code = atoi(p + 12);
        } else {
            int len = strlen(buf);
            if (total + len < MAX_BODY - 1) {
                strncat(resp->body, buf, MAX_BODY - total - 1);
                total += len;
            }
        }
    }

    pclose(fp);
}

/* ── FreeLang FFI 진입점 ── */

/**
 * fl_http_post(url, body, auth_token) -> body string
 * Claude API 전용: Authorization Bearer 자동 주입
 */
const char* fl_http_post_claude(const char *url, const char *body,
                                 const char *auth_token) {
    static HttpResponse resp;
    char auth_header[512];
    snprintf(auth_header, sizeof(auth_header), "Authorization: Bearer %s", auth_token);

    /* auth 헤더 재구성: x-api-key 방식 (Anthropic) */
    char xkey_header[512];
    snprintf(xkey_header, sizeof(xkey_header), "x-api-key: %s", auth_token);
    const char *claude_headers[] = {
        xkey_header,
        "anthropic-version: 2023-06-01",
        NULL
    };

    http_post(url, body, claude_headers, &resp);
    return resp.body;
}

/**
 * fl_http_get(url) -> body string
 */
const char* fl_http_get(const char *url) {
    static HttpResponse resp;
    http_get(url, NULL, &resp);
    return resp.body;
}

/**
 * fl_http_post_json(url, body) -> body string
 */
const char* fl_http_post_json(const char *url, const char *body) {
    static HttpResponse resp;
    http_post(url, body, NULL, &resp);
    return resp.body;
}

