/**
 * FAF Core — llm.free
 * Claude API 클라이언트
 *
 * 사용:
 *   import llm from "core/llm"
 *
 *   let resp = await llm.chat("fir Phase 3 실행해줘")
 *   let tool = await llm.chat_with_tools("nexus 빌드해줘", tools)
 */

import http from "stdlib/http"
import json from "stdlib/json"
import fs   from "stdlib/fs"

// ── 상수 ──
let CLAUDE_API_URL = "https://api.anthropic.com/v1/messages"
let CLAUDE_MODEL   = "claude-sonnet-4-6"
let MAX_TOKENS     = 4096

// ── API 키 로드 (환경변수 우선, 없으면 .env 파일) ──
fn load_api_key() {
  let key = $env.ANTHROPIC_API_KEY
  if key != "" && key != null
    return key

  // .env 파일에서 로드
  let env_path = "/data/data/com.termux/files/home/projects/faf/.env"
  let content = fs.readFileSync(env_path)
  if content != null {
    let lines = content.split("\n")
    for line in lines {
      if line.startsWith("ANTHROPIC_API_KEY=") {
        return line.slice(18).trim()
      }
    }
  }

  throw "ANTHROPIC_API_KEY not found. Set env var or create faf/.env"
}

// ── 메시지 빌더 ──
fn build_message(role, content) {
  return { role: role, content: content }
}

fn build_system_prompt() {
  return "당신은 FAF(FreeLang Agent Framework) 에이전트입니다. " +
         "FreeLang 생태계(fir, nexus, freelang-gpt)를 조율하고 관리합니다. " +
         "명령을 받으면 적절한 tool을 선택해 실행하고 결과를 보고합니다. " +
         "한국어로 응답합니다."
}

// ── Tool 정의 ──
let FAF_TOOLS = [
  {
    name: "nexus_build",
    description: "FreeLang .fl 파일을 C로 컴파일하고 바이너리 생성",
    input_schema: {
      type: "object",
      properties: {
        file: { type: "string", description: ".fl 파일 경로" },
        output: { type: "string", description: "출력 바이너리 이름 (선택)" }
      },
      required: ["file"]
    }
  },
  {
    name: "nexus_test",
    description: "freelang-nexus 테스트 스위트 실행",
    input_schema: {
      type: "object",
      properties: {
        filter: { type: "string", description: "특정 테스트 필터 (선택)" }
      }
    }
  },
  {
    name: "fir_opt",
    description: "fir IR 최적화 Pass 실행 (constfold, dce, mem2reg, regalloc)",
    input_schema: {
      type: "object",
      properties: {
        pass: { type: "string", description: "최적화 Pass 이름" },
        file: { type: "string", description: "IR 파일 경로 (선택)" }
      },
      required: ["pass"]
    }
  },
  {
    name: "git_push",
    description: "변경사항을 GOGS에 push",
    input_schema: {
      type: "object",
      properties: {
        project: { type: "string", description: "프로젝트 이름 (fir, nexus, gpt)" },
        message: { type: "string", description: "커밋 메시지" }
      },
      required: ["project", "message"]
    }
  },
  {
    name: "project_status",
    description: "FreeLang 프로젝트 전체 상태 조회",
    input_schema: {
      type: "object",
      properties: {
        project: { type: "string", description: "특정 프로젝트 (선택, 없으면 전체)" }
      }
    }
  },
  {
    name: "shell_exec",
    description: "임의 쉘 명령 실행 (주의: 안전한 명령만)",
    input_schema: {
      type: "object",
      properties: {
        command: { type: "string", description: "실행할 쉘 명령" }
      },
      required: ["command"]
    }
  }
]

// ── 핵심 API 호출 ──
async fn call_claude(messages, tools, use_tools) {
  let api_key = load_api_key()

  let body = {
    model: CLAUDE_MODEL,
    max_tokens: MAX_TOKENS,
    system: build_system_prompt(),
    messages: messages
  }

  if use_tools {
    body.tools = tools
  }

  let body_str = json.stringify(body)
  let resp_str = $ffi.fl_http_post_claude(CLAUDE_API_URL, body_str, api_key)

  if resp_str == null || resp_str == ""
    throw "Claude API: 응답 없음"

  let resp = json.parse(resp_str)
  if resp == null
    throw "Claude API: JSON 파싱 실패 — " + resp_str.slice(0, 200)

  if resp.error != null
    throw "Claude API 오류: " + resp.error.message

  return resp
}

// ── 공개 API ──

/**
 * llm.chat - 단순 텍스트 대화
 * @param user_msg: 사용자 메시지
 * @returns 응답 텍스트
 */
export async fn chat(user_msg) {
  let messages = [
    build_message("user", user_msg)
  ]

  let resp = await call_claude(messages, null, false)

  // content 배열에서 텍스트 추출
  if resp.content && resp.content.length > 0 {
    for block in resp.content {
      if block.type == "text"
        return block.text
    }
  }

  return ""
}

/**
 * llm.chat_with_tools - Tool use 포함 대화
 * @param user_msg: 사용자 메시지
 * @param tools:    Tool 정의 배열 (null이면 FAF_TOOLS 사용)
 * @returns { text, tool_use } 객체
 */
export async fn chat_with_tools(user_msg, tools) {
  let active_tools = tools != null ? tools : FAF_TOOLS
  let messages = [
    build_message("user", user_msg)
  ]

  let resp = await call_claude(messages, active_tools, true)

  let result = {
    text: "",
    tool_use: null,
    stop_reason: resp.stop_reason
  }

  if resp.content {
    for block in resp.content {
      if block.type == "text"
        result.text = block.text
      if block.type == "tool_use"
        result.tool_use = {
          name: block.name,
          input: block.input,
          id: block.id
        }
    }
  }

  return result
}

/**
 * llm.tools - 기본 FAF tool 목록 반환
 */
export fn tools() {
  return FAF_TOOLS
}

/**
 * llm.model - 현재 모델명 반환
 */
export fn model() {
  return CLAUDE_MODEL
}

