input.content:
/**
 * FAF Core — gateway.free
 * 메인 진입점 & 명령 디스패처
 *
 * 역할:
 *   1. stdin or args에서 사용자 명령 수신
 *   2. llm.free에 전달 → tool_use 응답
 *   3. 해당 Skill 실행
 *   4. 결과 출력 + memory에 기록
 *
 * 실행:
 *   faf "fir Phase 3 실행해줘"
 *   faf --daemon     (백그라운드 서버 모드)
 *   faf --status
 */

import llm    from "core/llm"
import memory from "core/memory"
import json   from "stdlib/json"
import fs     from "stdlib/fs"

// Skills
import nexus  from "skills/nexus/nexus"
import fir    from "skills/fir/fir"
import git    from "skills/git/git"

// ── 로깅 ──
fn log(level, msg) {
  let prefix = {
    info:  "[FAF] ",
    ok:    "[FAF] ✅ ",
    warn:  "[FAF] ⚠️  ",
    err:   "[FAF] ❌ ",
    think: "[FAF] 🤖 "
  }
  println((prefix[level] || "[FAF] ") + msg)
}

// ── Skill 디스패처 ──
async fn dispatch_tool(tool_name, tool_input) {
  log("info", "skill: " + tool_name + " 실행 중...")

  if tool_name == "nexus_build" {
    return await nexus.build(tool_input.file, tool_input.output)
  }

  if tool_name == "nexus_test" {
    return await nexus.test(tool_input.filter)
  }

  if tool_name == "fir_opt" {
    return await fir.opt(tool_input.pass, tool_input.file)
  }

  if tool_name == "git_push" {
    return await git.push(tool_input.project, tool_input.message)
  }

  if tool_name == "project_status" {
    return await dispatch_status(tool_input.project)
  }

  if tool_name == "shell_exec" {
    return await dispatch_shell(tool_input.command)
  }

  return "알 수 없는 tool: " + tool_name
}

// ── 프로젝트 상태 조회 ──
async fn dispatch_status(project) {
  let FIR_PATH   = "/data/data/com.termux/files/home/.projects/core/freelang-v7"
  let NEXUS_PATH = "/data/data/com.termux/files/home/projects/freelang-nexus"
  let GPT_PATH   = "/data/data/com.termux/files/home/projects/freelang-gpt"

  if project == "fir" || project == null {
    let result = $ffi.fl_process_exec_simple("cd " + FIR_PATH + " && git log --oneline -3 2>/dev/null || echo 'git 없음'")
    return "fir 최근 커밋:\n" + result
  }

  if project == "nexus" {
    let result = $ffi.fl_process_exec_simple("cd " + NEXUS_PATH + " && git log --oneline -3 2>/dev/null || echo 'git 없음'")
    return "nexus 최근 커밋:\n" + result
  }

  // 전체 상태
  let fir_log   = $ffi.fl_process_exec_simple("cd " + FIR_PATH   + " && git log --oneline -1 2>/dev/null")
  let nexus_log = $ffi.fl_process_exec_simple("cd " + NEXUS_PATH + " && git log --oneline -1 2>/dev/null")
  let gpt_log   = $ffi.fl_process_exec_simple("cd " + GPT_PATH   + " && git log --oneline -1 2>/dev/null")

  return "=== FreeLang 프로젝트 상태 ===\n" +
         "fir:   " + fir_log + "\n" +
         "nexus: " + nexus_log + "\n" +
         "gpt:   " + gpt_log
}

// ── 쉘 명령 실행 ──
async fn dispatch_shell(command) {
  // 위험 명령 차단
  let BLOCKED = ["rm -rf", "dd if=", "mkfs", "shutdown", "reboot", "> /dev"]
  for blocked in BLOCKED {
    if command.indexOf(blocked) >= 0
      return "❌ 차단된 명령: " + blocked
  }

  let out = { stdout: "", exitCode: 0 }
