/**
 * FAF Skill — skills/nexus/nexus.free
 * freelang-nexus 빌드/테스트/실행 제어
 *
 * 명령:
 *   nexus run <file>      .fl 파일 실행
 *   nexus compile <file>  C 코드 출력
 *   nexus check <file>    문법 검사
 *   nexus test            테스트 스위트 실행
 */

let NEXUS_PATH = "/data/data/com.termux/files/home/projects/freelang-nexus"
let NEXUS_BIN  = "node " + NEXUS_PATH + "/dist/nexus/index.js"

// ── 내부 실행 헬퍼 ──
fn run(cmd) {
  let out = { stdout: "", exitCode: 0 }
  $ffi.fl_process_exec(cmd, out.stdout, out.exitCode)
  return out
}

fn format_result(action, file, out) {
  let status = out.exitCode == 0 ? "✅" : "❌"
  let header = status + " nexus " + action + (file ? (" — " + file) : "")
  return header + "\n" + (out.stdout || "(출력 없음)")
}

// ── 공개 API ──

/**
 * nexus.build — .fl 파일 컴파일
 * @file:   .fl 파일 경로
 * @output: 출력 이름 (선택)
 */
export async fn build(file, output) {
  if file == null || file == ""
    return "❌ nexus.build: file 경로 필요"

  let cmd = NEXUS_BIN + " compile '" + file + "'"
  if output != null
    cmd = cmd + " -o '" + output + "'"

  let out = run(cmd)
  return format_result("compile", file, out)
}

/**
 * nexus.run_file — .fl 파일 실행
 */
export async fn run_file(file) {
  if file == null || file == ""
    return "❌ nexus.run: file 경로 필요"

  let cmd = NEXUS_BIN + " run '" + file + "'"
  let out = run(cmd)
  return format_result("run", file, out)
}

/**
 * nexus.check — 문법 검사
 */
export async fn check(file) {
  if file == null || file == ""
    return "❌ nexus.check: file 경로 필요"

  let cmd = NEXUS_BIN + " check '" + file + "'"
  let out = run(cmd)
  return format_result("check", file, out)
}

/**
 * nexus.test — 테스트 스위트 실행
 * @filter: 특정 테스트 이름 필터 (선택)
 */
export async fn test(filter) {
  let cmd = "cd " + NEXUS_PATH + " && npm test 2>&1"
  if filter != null
    cmd = "cd " + NEXUS_PATH + " && npx jest '" + filter + "' 2>&1"

  let out = run(cmd)

  // 결과 파싱: passed/failed 추출
  let summary = parse_test_summary(out.stdout)
  return "🧪 nexus test" + (filter ? (" [" + filter + "]") : "") + "\n" +
         summary + "\n\n" + out.stdout.slice(-500)
}

/**
 * nexus.version — 버전 확인
 */
export async fn version() {
  let out = run(NEXUS_BIN + " --version")
  return out.stdout.trim()
}

/**
 * nexus.status — 프로젝트 상태 요약
