let VALID_PASSES = ["constfold", "dce", "mem2reg", "regalloc", "struct", "gep"]

// ── 내부 실행 헬퍼 ──
fn run(cmd) {
  let out = { stdout: "", exitCode: 0 }
  $ffi.fl_process_exec(cmd, out.stdout, out.exitCode)
  return out
}

// ── 공개 API ──

/**
 * fir.opt — 최적화 Pass 실행
 * @pass: "constfold" | "dce" | "mem2reg" | "regalloc" | "struct" | "gep"
 * @file: IR 파일 경로 (선택, 없으면 전체 테스트)
 */
export async fn opt(pass, file) {
  if pass == null || pass == ""
    return "❌ fir.opt: pass 이름 필요 (" + VALID_PASSES.join(", ") + ")"

  // Pass 검증
  let valid = false
  for p in VALID_PASSES {
    if p == pass { valid = true }
  }
  if !valid
    return "❌ 알 수 없는 pass: " + pass + "\n지원: " + VALID_PASSES.join(", ")

  let cmd = FIR_RUN + " opt --pass " + pass
  if file != null && file != ""
    cmd = cmd + " --file '" + file + "'"

  let before_time = $time.now()
  let out = run(cmd)
  let after_time = $time.now()

  let status = out.exitCode == 0 ? "✅" : "❌"
  let result = status + " fir opt --pass " + pass + "\n"

  // 결과 파싱
  let summary = parse_opt_result(out.stdout, pass)
  result = result + summary + "\n\n"
  result = result + out.stdout.slice(0, 800)

  return result
}

/**
 * fir.test — 전체 테스트 실행
 */
export async fn test() {
  let cmd = FIR_RUN + " test 2>&1"
  let out = run(cmd)

  let lines = out.stdout.split("\n")
  let passed = 0
  let failed = 0
  for line in lines {
    if line.indexOf("PASS") >= 0  { passed = passed + 1 }
    if line.indexOf("FAIL") >= 0  { failed = failed + 1 }
  }

  let status = failed == 0 ? "✅" : "❌"
  return status + " fir test — " + passed + " PASS / " + failed + " FAIL\n\n" +
         out.stdout.slice(-600)
}

