  if file == null
    return "❌ fir.bench: file 경로 필요"

  // 최적화 전
  let before_cmd = FIR_RUN + " interp '" + file + "' --bench"
  let before = run(before_cmd)

  // 최적화 적용
  let opt_cmd = FIR_RUN + " opt --pass " + pass + " --file '" + file + "'"
  run(opt_cmd)

  // 최적화 후
  let after = run(before_cmd)

  return "📊 fir bench — pass: " + pass + "\n" +
         "최적화 전:\n" + before.stdout + "\n" +
         "최적화 후:\n" + after.stdout
}

/**
