 */
export async fn status() {
  let git_log  = run("cd " + FIR_PATH + " && git log --oneline -5")
  let phase    = run("cd " + FIR_PATH + " && ls *.md | head -5")
  let src_list = run("cd " + FIR_PATH + "/src && find . -name '*.fl' | head -10")

  return "=== fir 상태 ===\n" +
