         "최근 커밋:\n" + git_log.stdout + "\n" +
         ".fl 소스 파일:\n" + src_list.stdout
}

/**
 * fir.phase3 — Phase 3 전체 Pass 순서대로 실행
 * constfold → dce → struct/gep → mem2reg → regalloc
 */
export async fn phase3() {
  let passes = ["constfold", "dce", "struct", "gep", "mem2reg", "regalloc"]
  let results = []

  for pass in passes {
    let result = await opt(pass, null)
    results.push("── " + pass + " ──\n" + result)
  }

  return "🚀 fir Phase 3 전체 실행\n\n" + results.join("\n\n")
}

// ── 내부 헬퍼 ──
fn parse_opt_result(output, pass) {
  // 최적화 결과에서 핵심 수치 추출
  let lines = output.split("\n")
  for line in lines {
    if line.indexOf("folded") >= 0  { return "상수 폴딩: " + line.trim() }
    if line.indexOf("removed") >= 0 { return "제거됨: " + line.trim() }
    if line.indexOf("pass") >= 0    { return line.trim() }
    if line.indexOf("PASS") >= 0    { return line.trim() }
  }
  return "(결과 파싱 중)"
}

