/**
 * FAF Skill — skills/git/git.free
 * GOGS push / PR / 상태 관리
 *
 * GOGS: https://gogs.dclub.kr/kim/
 * 저장소:
 *   fir   → gogs.dclub.kr/kim/fir.git
 *   nexus → gogs.dclub.kr/kim/freelang-nexus.git
 *   gpt   → gogs.dclub.kr/kim/freelang-gpt.git (예정)
 *   faf   → gogs.dclub.kr/kim/faf.git
 */

let PROJECTS = {
  fir:   "/data/data/com.termux/files/home/.projects/core/freelang-v7",
  nexus: "/data/data/com.termux/files/home/projects/freelang-nexus",
  gpt:   "/data/data/com.termux/files/home/projects/freelang-gpt",
  faf:   "/data/data/com.termux/files/home/projects/faf"
}

let GOGS_BASE = "https://gogs.dclub.kr/kim"

// ── 내부 실행 헬퍼 ──
fn run(cmd) {
  let out = { stdout: "", exitCode: 0 }
  $ffi.fl_process_exec(cmd, out.stdout, out.exitCode)
  return out
}

fn project_path(project) {
  let path = PROJECTS[project]
  if path == null
    return null
  return path
}

// ── 공개 API ──

/**
 * git.status — 프로젝트 git 상태 확인
 */
export async fn status(project) {
  let path = project_path(project)
  if path == null
    return "❌ 알 수 없는 프로젝트: " + project + " (fir, nexus, gpt, faf)"

  let st  = run("cd " + path + " && git status --short")
  let log = run("cd " + path + " && git log --oneline -3")

  return "📁 " + project + " (" + path + ")\n" +
         "변경사항:\n" + (st.stdout || "(없음)") + "\n" +
         "최근 커밋:\n" + log.stdout
}

/**
 * git.push — 변경사항 커밋 + push
 * @project: "fir" | "nexus" | "gpt" | "faf"
 * @message: 커밋 메시지
 */
export async fn push(project, message) {
  let path = project_path(project)
  if path == null
    return "❌ 알 수 없는 프로젝트: " + project

  if message == null || message == ""
    return "❌ git.push: 커밋 메시지 필요"

  // 1. 변경사항 확인
  let st = run("cd " + path + " && git status --short")
  if st.stdout.trim() == ""
    return "ℹ️  " + project + ": 변경사항 없음"

  // 2. add + commit
  let add    = run("cd " + path + " && git add -A")
  let commit = run("cd " + path + " && git commit -m '" + message + " (via FAF)'")
  if commit.exitCode != 0
    return "❌ commit 실패:\n" + commit.stdout

  // 3. push
  let push_out = run("cd " + path + " && git push origin master 2>&1")
  let status = push_out.exitCode == 0 ? "✅" : "❌"

  return status + " git push — " + project + "\n" +
         "커밋: " + message + "\n" +
         push_out.stdout
}

/**
 * git.pull — 최신 변경사항 가져오기
 */
export async fn pull(project) {
  let path = project_path(project)
  if path == null
    return "❌ 알 수 없는 프로젝트: " + project

  let out = run("cd " + path + " && git pull origin master 2>&1")
  let status = out.exitCode == 0 ? "✅" : "❌"
  return status + " git pull — " + project + "\n" + out.stdout
}

/**
 * git.log — 최근 커밋 로그
 * @n: 개수 (기본 5)
 */
export async fn log(project, n) {
  let path = project_path(project)
  if path == null
    return "❌ 알 수 없는 프로젝트: " + project

  let count = n != null ? n : 5
  let out = run("cd " + path + " && git log --oneline -" + count)
  return "📋 " + project + " 최근 " + count + "개 커밋:\n" + out.stdout
}

/**
 * git.diff — 변경 내용 확인
 */
export async fn diff(project) {
  let path = project_path(project)
  if path == null
    return "❌ 알 수 없는 프로젝트: " + project

  let out = run("cd " + path + " && git diff --stat HEAD 2>&1")
  return "🔍 " + project + " diff:\n" + (out.stdout || "(변경 없음)")
}

/**
 * git.push_all — 전체 프로젝트 동시 push
 * @message: 공통 커밋 메시지
 */
export async fn push_all(message) {
  let projects = ["fir", "nexus", "faf"]
  let results = []

  for proj in projects {
    let result = await push(proj, message)
    results.push(result)
  }

  return "🚀 전체 push 완료\n\n" + results.join("\n\n---\n\n")
}

/**
 * git.sync_status — 전체 프로젝트 동기화 상태
 */
export async fn sync_status() {
  let projects = ["fir", "nexus", "gpt", "faf"]
  let lines = ["=== GOGS 동기화 상태 ===\n"]

  for proj in projects {
    let path = PROJECTS[proj]
    if path == null {
      lines.push("  " + proj + ": ❓ 경로 없음")
    } else {
      let ahead  = run("cd " + path + " && git rev-list HEAD...origin/master --count 2>/dev/null")
      let status = ahead.stdout.trim() == "0" ? "✅ 동기화됨" : ("⚠️  " + ahead.stdout.trim() + "개 미push")
      lines.push("  " + proj + ": " + status)
    }
  }

  return lines.join("\n")
}

