/**
 * FAF Heartbeat — heartbeat/scheduler.free
 * 자율 실행 스케줄러
 *
 * 스케줄:
 *   매일 09:00 — 프로젝트 상태 체크 + 이상 감지
 *   매일 22:00 — 일일 리포트 생성 + memory 저장
 *   매시간     — 빠른 헬스체크
 */

import timer    from "stdlib/timer"
import memory   from "core/memory"
import report   from "heartbeat/report"
import fir      from "skills/fir/fir"
import nexus    from "skills/nexus/nexus"
import git      from "skills/git/git"

// ── 상수 ──
let SCHEDULE = {
  morning:  9,   // 09:00 상태 체크
  evening:  22,  // 22:00 일일 리포트
  interval: 60   // 분 단위 헬스체크
}

let LOG_PATH = "/data/data/com.termux/files/home/projects/faf/memory/heartbeat.log"

// ── 로깅 ──
fn hlog(msg) {
  let ts = $time.now().slice(0, 19)
  let line = "[" + ts + "] [HB] " + msg
  println(line)
  $ffi.fl_process_exec("echo '" + line + "' >> " + LOG_PATH, "", 0)
}

// ── 현재 시간 (시) 반환 ──
fn current_hour() {
  let now = $time.now()
  // "2026-03-23T09:00:00" → 9
  return int_cast(now.slice(11, 13))
}

// ── 헬스체크 ──
async fn health_check() {
  hlog("헬스체크 시작")

  let issues = []

  // fir 빌드 가능 여부
  let fir_ok = $ffi.fl_process_exec_simple(
    "cd /data/data/com.termux/files/home/.projects/core/freelang-v7 && go build ./src/cmd/... 2>&1"
  )
  if fir_ok.indexOf("error") >= 0 {
    issues.push("fir 빌드 오류: " + fir_ok.slice(0, 100))
  }

  // nexus 실행 가능 여부
  let nexus_ok = $ffi.fl_process_exec_simple(
    "node /data/data/com.termux/files/home/projects/freelang-nexus/dist/nexus/index.js --version 2>&1"
  )
  if nexus_ok.trim() == "" {
    issues.push("nexus 응답 없음")
  }

  // GOGS 연결
  let gogs_ok = $ffi.fl_process_exec_simple(
    "curl -s -o /dev/null -w '%{http_code}' https://gogs.dclub.kr 2>/dev/null"
  )
  if gogs_ok.trim() != "200" && gogs_ok.trim() != "302" {
    issues.push("GOGS 연결 불안정: " + gogs_ok.trim())
  }

  if issues.length == 0 {
    hlog("헬스체크 PASS — 모든 시스템 정상")
    return { ok: true, issues: [] }
  } else {
    hlog("헬스체크 FAIL — " + issues.length + "개 이슈")
    for issue in issues { hlog("  ⚠️  " + issue) }
    return { ok: false, issues: issues }
  }
}

// ── 09:00 아침 체크 ──
async fn morning_check() {
  hlog("=== 아침 상태 체크 시작 (09:00) ===")

  // 1. 헬스체크
  let health = await health_check()

  // 2. 각 프로젝트 git 상태
  let sync = await git.sync_status()
  hlog(sync)

  // 3. fir Phase 3 진행상황
  let fir_status = await fir.status()

  // 4. 상태 저장
  await memory.save_state("heartbeat", {
    type: "morning_check",
    health: health,
    sync: sync,
    fir_status: fir_status
  })

  // 5. 이슈 있으면 알림
  if !health.ok {
    hlog("🚨 이슈 감지 — 확인 필요: " + health.issues.join(", "))
  }

  hlog("=== 아침 체크 완료 ===")
}

// ── 22:00 저녁 리포트 ──
async fn evening_report() {
  hlog("=== 일일 리포트 생성 시작 (22:00) ===")

  let rep = await report.daily()
  hlog("리포트 생성 완료: " + rep.date)

  // git push (faf 리포트 자동 커밋)
  let push_result = await git.push("faf", "📊 일일 리포트 " + rep.date)
  hlog(push_result)

  hlog("=== 일일 리포트 완료 ===")
}

// ── 메인 루프 ──
export async fn start() {
  hlog("FAF Heartbeat 시작")
  hlog("스케줄: 아침=" + SCHEDULE.morning + "시, 저녁=" + SCHEDULE.evening + "시")

  let last_morning = -1
  let last_evening = -1

  // timer 기반 매분 체크
  timer.setInterval(async () => {
    let hour = current_hour()

    // 아침 체크 (09:00, 하루 1회)
    if hour == SCHEDULE.morning && last_morning != hour {
      last_morning = hour
      await morning_check()
    }

    // 저녁 리포트 (22:00, 하루 1회)
    if hour == SCHEDULE.evening && last_evening != hour {
      last_evening = hour
      await evening_report()
    }

  }, SCHEDULE.interval * 60 * 1000)  // ms 단위

  hlog("Heartbeat 루프 실행 중... (Ctrl+C로 중단)")
}

// ── 수동 실행 ──
export async fn run_now(type) {
  if type == "morning" {
    await morning_check()
  } else if type == "evening" {
    await evening_report()
  } else if type == "health" {
    let h = await health_check()
    println(h.ok ? "✅ 모든 시스템 정상" : "❌ 이슈: " + h.issues.join(", "))
  } else {
    println("사용: run_now('morning' | 'evening' | 'health')")
  }
}

