/**
 * FAF Heartbeat — heartbeat/report.free
 * 일일 리포트 생성기
 *
 * 출력:
 *   memory/episodic/YYYY-MM-DD-report.md
 *   memory/project-state/ 각 프로젝트 스냅샷
 */

import fs     from "stdlib/fs"
import json   from "stdlib/json"
import memory from "core/memory"
import fir    from "skills/fir/fir"
import nexus  from "skills/nexus/nexus"
import git    from "skills/git/git"

let REPORT_DIR = "/data/data/com.termux/files/home/projects/faf/memory/episodic"

// ── 날짜 ──
fn today() {
  return $time.now().slice(0, 10)
}

fn now_str() {
  return $time.now().slice(0, 19).replace("T", " ")
}

// ── 섹션 빌더 ──
fn section(title, content) {
  return "\n## " + title + "\n\n" + content + "\n"
}

fn code_block(lang, content) {
  return "```" + lang + "\n" + content + "\n```"
}

// ── 데이터 수집 ──
async fn collect_fir() {
  let status = await fir.status()
  let git_log = $ffi.fl_process_exec_simple(
    "cd /data/data/com.termux/files/home/.projects/core/freelang-v7 && git log --oneline -5"
  )
  return {
    status: status,
    git_log: git_log,
    phase: "Phase 3 진행 중 (constfold→dce→struct→mem2reg→regalloc)"
  }
}

async fn collect_nexus() {
  let ver = await nexus.version()
  let git_log = $ffi.fl_process_exec_simple(
    "cd /data/data/com.termux/files/home/projects/freelang-nexus && git log --oneline -5"
  )
  return {
    version: ver,
    git_log: git_log
  }
}

async fn collect_episodes() {
  let episodes = await memory.list_episodes(null)
  if episodes.length == 0
    return "(오늘 실행 없음)"

  let lines = []
  for ep in episodes {
    lines.push("- [" + ep.timestamp.slice(11, 19) + "] " +
               ep.tool + " — " + ep.user_input.slice(0, 60))
  }
  return lines.join("\n")
}

async fn collect_git_sync() {
  return await git.sync_status()
}

// ── 리포트 생성 ──

/**
 * report.daily — 일일 리포트 생성
 * @returns { date, path, content }
 */
export async fn daily() {
  let date = today()
  let path = REPORT_DIR + "/" + date + "-report.md"

  // 데이터 수집 (병렬)
  let fir_data    = await collect_fir()
  let nexus_data  = await collect_nexus()
  let episodes    = await collect_episodes()
  let git_sync    = await collect_git_sync()

  // 마크다운 리포트 조립
  let content = "# FAF 일일 리포트 — " + date + "\n\n" +
    "> 생성: " + now_str() + " | FAF Heartbeat 자동 생성\n"

  // 1. 요약
  content = content + section("요약",
    "| 항목 | 상태 |\n" +
    "|------|------|\n" +
    "| fir Phase 3 | 🔥 진행 중 |\n" +
    "| nexus | ✅ " + nexus_data.version.trim() + " |\n" +
    "| FAF | ✅ v0.1 운영 중 |\n" +
    "| GOGS | ✅ 연결됨 |"
  )

  // 2. 오늘 실행 로그
  content = content + section("오늘 실행 로그", episodes)

  // 3. fir 상태
  content = content + section("fir (Free IR Platform)",
    "**Phase**: " + fir_data.phase + "\n\n" +
    "**최근 커밋**:\n" + code_block("", fir_data.git_log)
  )

  // 4. nexus 상태
  content = content + section("freelang-nexus",
    "**버전**: " + nexus_data.version.trim() + "\n\n" +
    "**최근 커밋**:\n" + code_block("", nexus_data.git_log)
  )

  // 5. GOGS 동기화
