    FILE *f = fopen(filename, "rb");
    if (!f) {
        perror("Cannot open input file");
        return NULL;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *buffer = malloc(size + 1);
